func Test_matchListenPorts(t *testing.T) {
	type args struct {
		listenIPPorts    []string
		searchPort models.PortStat
	}
	tests := []struct {
		name   string
		args   args
		expect []string
	}{
		{name: "open_empty", args: args{listenIPPorts: []string{}, searchPort: models.PortStat{BindAddress: "127.0.0.1", Port: "22"}}, expect: []string{}},
		{name: "port_empty", args: args{listenIPPorts: []string{"127.0.0.1:22"}, searchPort: models.PortStat{}}, expect: []string{}},
		{name: "single_match", args: args{listenIPPorts: []string{"127.0.0.1:22"}, searchPort: models.PortStat{BindAddress: "127.0.0.1", Port: "22"}}, expect: []string{"127.0.0.1"}},
		{name: "no_match_address", args: args{listenIPPorts: []string{"127.0.0.1:22"}, searchPort: models.PortStat{BindAddress: "192.168.1.1", Port: "22"}}, expect: []string{}},
		{name: "no_match_port", args: args{listenIPPorts: []string{"127.0.0.1:22"}, searchPort: models.PortStat{BindAddress: "127.0.0.1", Port: "80"}}, expect: []string{}},
		{name: "asterisk_match", args: args{listenIPPorts: []string{"127.0.0.1:22", "127.0.0.1:80", "192.168.1.1:22"}, searchPort: models.PortStat{BindAddress: "*", Port: "22"}}, expect: []string{"127.0.0.1", "192.168.1.1"}},
	}

	l := base{}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if match := l.findPortReachableTo(tt.args.listenIPPorts, tt.args.searchPort); !reflect.DeepEqual(match, tt.expect) {
				t.Errorf("findPortReachableTo() = %v, want %v", match, tt.expect)
			}
		})
	}
}

func Test_base_parseListenPorts(t *testing.T) {
	tests := []struct {
		name   string
		args   string
		expect models.PortStat
	}{{
		name: "empty",
		args: "",
		expect: models.PortStat{
			BindAddress: "",
			Port:    "",
		},
	}, {
		name: "normal",
		args: "127.0.0.1:22",
		expect: models.PortStat{
			BindAddress: "127.0.0.1",
			Port:    "22",
		},
	}, {
		name: "asterisk",
		args: "*:22",
		expect: models.PortStat{
			BindAddress: "*",
			Port:    "22",
		},
	}, {
		name: "ipv6_loopback",
		args: "[::1]:22",
		expect: models.PortStat{
			BindAddress: "[::1]",
			Port:    "22",
		},
	}}

	l := base{}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if listenPort := l.parseListenPorts(tt.args); !reflect.DeepEqual(listenPort, tt.expect) {
				t.Errorf("base.parseListenPorts() = %v, want %v", listenPort, tt.expect)
			}
		})
	}
}
